const primmbaseMediaDetails=[
 {file:'landing.png',title:'PRIMMBASE Landing Page',titleId:'Halaman Landing PRIMMBASE',description:'An interactive e-LKPD platform for learning database concepts through the PRIMM approach, with support from a virtual assistant.',descriptionId:'Platform e-LKPD interaktif untuk mempelajari konsep basis data dengan pendekatan PRIMM dan bantuan asisten virtual.',fullDescription:'The landing page introduces PRIMMBASE as an interactive learning platform for database topics. It presents the PRIMM learning approach and provides entry points to begin learning or explore the platform.',fullDescriptionId:'Halaman landing memperkenalkan PRIMMBASE sebagai platform pembelajaran interaktif untuk materi basis data. Halaman ini menjelaskan pendekatan PRIMM dan menyediakan akses untuk mulai belajar atau mengenal platform.'},
 {file:'dashboard-siswa.png',title:'Student Dashboard',titleId:'Dashboard Siswa',description:'The student dashboard brings together learning activities and results, with direct access to worksheets and completed learning.',descriptionId:'Dashboard siswa merangkum aktivitas dan hasil belajar, dengan akses langsung ke LKPD dan pembelajaran yang telah diselesaikan.',fullDescription:'Students can continue their learning from a dashboard with separate entry points for interactive worksheets (LKPD) and learning results. The interface also shows the signed-in student and a personalized welcome.',fullDescriptionId:'Siswa dapat melanjutkan belajar dari dashboard yang menyediakan akses ke lembar kerja interaktif (LKPD) dan hasil belajar. Antarmuka juga menampilkan akun siswa yang sedang masuk dan sapaan personal.'},
 {file:'daftar-lkpd.png',title:'Learning Worksheet Catalog',titleId:'Katalog LKPD',description:'Students browse database learning worksheets and see course enrollment and completion progress.',descriptionId:'Siswa menjelajahi LKPD basis data serta melihat status pendaftaran course dan progres penyelesaian.',fullDescription:'The LKPD catalog presents database learning courses, including DML fundamentals and operators. Course cards show enrollment or continuation actions and learning progress so students can choose where to begin or resume.',fullDescriptionId:'Katalog LKPD menampilkan course pembelajaran basis data, termasuk materi dasar DML dan operator. Kartu course memuat aksi untuk mendaftar atau melanjutkan serta progres belajar, sehingga siswa dapat memilih materi baru atau meneruskan pembelajaran.'},
 {file:'aktivitas-investigate.png',title:'PRIMM Investigate Workspace',titleId:'Ruang Aktivitas Investigate PRIMM',description:'In Investigate, students edit and run SQL queries, inspect the database, and answer guided analysis questions.',descriptionId:'Pada tahap Investigate, siswa mengubah dan menjalankan kueri SQL, memeriksa basis data, serta menjawab pertanyaan analisis terarah.',fullDescription:'The Investigate workspace combines an editable SQL editor, database tables, and a guided question panel. Students can test query changes and explain how individual SQL clauses affect the results as part of the PRIMM learning sequence.',fullDescriptionId:'Ruang Investigate menggabungkan editor SQL yang dapat diubah, tabel basis data, dan panel pertanyaan terarah. Siswa dapat mencoba perubahan kueri dan menjelaskan pengaruh tiap klausa SQL terhadap hasil sebagai bagian dari tahapan belajar PRIMM.'},
 {file:'diskusi-ai.png',title:'AI-Supported Learning Discussion',titleId:'Diskusi Pembelajaran Berbantuan AI',description:'The virtual assistant guides students to reflect on their predictions and SQL results before moving to the next learning stage.',descriptionId:'Asisten virtual memandu siswa merefleksikan prediksi dan hasil SQL sebelum melanjutkan ke tahap belajar berikutnya.',fullDescription:'During the Investigate AI Chat phase, students discuss their predictions and query results with the PRIMMBASE assistant. The conversation is designed to prompt reflection on what matched, what differed, and why before formal investigation continues.',fullDescriptionId:'Pada tahap Investigate AI Chat, siswa mendiskusikan prediksi dan hasil kueri bersama asisten PRIMMBASE. Percakapan membantu siswa merefleksikan bagian yang sesuai, yang berbeda, dan alasannya sebelum melanjutkan ke investigasi formal.'},
 {file:'dashboard-admin.png',title:'Administrator Analytics Dashboard',titleId:'Dashboard Analitik Administrator',description:'Administrators get an overview of students, worksheets, activities, submissions, and activity across PRIMM stages.',descriptionId:'Administrator mendapat ringkasan siswa, LKPD, aktivitas, pengumpulan, dan aktivitas pada tiap tahap PRIMM.',fullDescription:'The admin dashboard summarizes platform activity through counts of students, LKPDs, activities, and submissions. A chart compares submissions across Predict, Run, Investigate, Modify, and Make to help administrators review participation across the PRIMM stages.',fullDescriptionId:'Dashboard admin merangkum aktivitas platform melalui jumlah siswa, LKPD, aktivitas, dan pengumpulan. Grafik membandingkan pengumpulan pada tahap Predict, Run, Investigate, Modify, dan Make untuk membantu administrator meninjau partisipasi di setiap tahap PRIMM.'},
 {file:'kontrol-sesi-sinkron.png',title:'Synchronous Lesson Session Controls',titleId:'Kontrol Sesi Pembelajaran Sinkron',description:'Teachers can follow the lesson phase timeline and pause, resume, skip, or end a synchronized class session.',descriptionId:'Guru dapat mengikuti linimasa tahap pembelajaran serta menjeda, melanjutkan, melewati, atau mengakhiri sesi kelas sinkron.',fullDescription:'The session control page shows the sequence and status of lesson phases in a synchronized chapter. Teachers can monitor the active phase and manage the class timer with controls to pause, skip a phase, or end the session.',fullDescriptionId:'Halaman kontrol sesi menampilkan urutan dan status tahap pembelajaran pada chapter yang berjalan secara sinkron. Guru dapat memantau fase aktif dan mengatur timer kelas dengan kontrol untuk menjeda, melewati fase, atau mengakhiri sesi.'},
 {file:'pemantauan-siswa.png',title:'Live Student Progress Monitoring',titleId:'Pemantauan Progres Siswa Langsung',description:'Teachers can review each student’s overall progress and completion status across individual PRIMM activities.',descriptionId:'Guru dapat meninjau progres keseluruhan dan status penyelesaian tiap siswa pada aktivitas PRIMM.',fullDescription:'The live monitoring view lists students, their completion percentages, and status for activities in each PRIMM phase. This helps teachers see who has completed a step and where students may need support during a synchronized lesson.',fullDescriptionId:'Tampilan pemantauan langsung mencantumkan siswa, persentase penyelesaian, dan status aktivitas pada setiap tahap PRIMM. Informasi ini membantu guru melihat tahap yang sudah diselesaikan dan mengetahui siswa yang mungkin memerlukan pendampingan selama pembelajaran sinkron.'},
];
